for req in all_requests:
    sender = req['sender']
    # Check if sender matches any roommate by email or name
    if sender['email'] in roommate_emails or sender['name'] in roommate_names:
        # Check if created in June 2023
        if req['created_at'].startswith('2023-06'):
            june_requests.append(req)

print(f"June roommate requests: {len(june_requests)}")
